#!/usr/bin/env node
/*
 * Regenerate demo-data.js from the C sources in demo/.
 *
 * The browser cannot fetch() sibling files when index.html is opened over
 * file://, so the demo codebase is embedded as a plain script instead. The
 * generated file is committed, which is what keeps "open index.html" a
 * complete install story with no build step for anyone cloning this repo.
 *
 * Sources are embedded with String.raw, so the C text appears verbatim and
 * there is no escaping to get wrong. The only two sequences that would break
 * that are a backtick and ${, so this refuses to run if it sees either rather
 * than emitting a file that does not parse.
 *
 *   node tools/bundle-demo.js
 */
'use strict';

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const demoDir = path.join(root, 'demo');
const outFile = path.join(root, 'demo-data.js');

/* Headers before their implementations, so the generated file reads in the
 * same order a person would open them. */
const ORDER = ['arena.h', 'arena.c', 'json.h', 'json.c', 'main.c'];

const names = fs.readdirSync(demoDir)
  .filter((n) => /\.(c|h)$/.test(n))
  .sort((a, b) => {
    const ia = ORDER.indexOf(a);
    const ib = ORDER.indexOf(b);
    return (ia < 0 ? ORDER.length : ia) - (ib < 0 ? ORDER.length : ib) ||
      a.localeCompare(b);
  });

if (names.length === 0) {
  console.error('bundle-demo: no C sources found in demo/');
  process.exit(1);
}

const files = names.map((name) => {
  const text = fs.readFileSync(path.join(demoDir, name), 'utf8');
  if (text.includes('`') || text.includes('${')) {
    console.error(
      'bundle-demo: ' + name + ' contains a backtick or ${, which String.raw ' +
      'cannot carry. Remove it from the source, or switch this generator to ' +
      'JSON.stringify.');
    process.exit(1);
  }
  if (text.endsWith('\\')) {
    console.error('bundle-demo: ' + name + ' ends in a backslash, which would ' +
      'escape the closing backtick.');
    process.exit(1);
  }
  return { path: 'jsonfmt/' + name, text };
});

const body = files.map((f) =>
  "  files.push({ path: '" + f.path + "', text: String.raw`" + f.text + '` });\n'
).join('\n');

const out = `/* GENERATED by tools/bundle-demo.js -- do not edit by hand.
 * Source of truth: demo/*.c, demo/*.h
 * Regenerate with: node tools/bundle-demo.js
 *
 * Each source is embedded with String.raw so the C text appears verbatim, with
 * no escaping to get wrong. The generator refuses to run if any source contains
 * a backtick or \${, which are the only two sequences that would break it.
 */
(function (root) {
  'use strict';
  var files = [];

${body}
  var api = {
    name: 'jsonfmt',
    blurb: 'An arena-allocating JSON reader and pretty printer in C.',
    files: files
  };
  if (typeof module === 'object' && module.exports) module.exports = api;
  root.LECTERN_DEMO = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);
`;

fs.writeFileSync(outFile, out, 'utf8');

const bytes = files.reduce((a, f) => a + f.text.length, 0);
const lines = files.reduce((a, f) => a + f.text.split('\n').length, 0);
console.log(
  'bundle-demo: wrote demo-data.js (' + files.length + ' files, ' +
  lines + ' lines, ' + bytes + ' bytes)');
